// FlowKit · Cobros vencidos — Parte A (clasificación y redacción)
// Ajusta estas constantes antes de activar el flujo.
const BASE_URL = 'https://TU-N8N.example.com';
const EMPRESA = 'Tu asesoría';
const IBAN = 'ES00 0000 0000 0000 0000 0000';
const DIAS_NIVEL1 = 5;
const DIAS_NIVEL2 = 15;
const DIAS_NIVEL3 = 30;
const LINK_PATH = '/webhook/flowkit-cobro';

const NL = String.fromCharCode(10);
const HOY = new Date();
HOY.setHours(0, 0, 0, 0);
const HOY_ISO = iso(HOY);

function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function fecha(d) { return pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear(); }
function mk(y, m, d) {
  const dt = new Date(y, m - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;
  return dt;
}
function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (!s) return null;
  if (s.length >= 10 && s.charAt(4) === '-') s = s.slice(0, 10);
  let p = s.split('/');
  if (p.length === 3) return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  p = s.split('-');
  if (p.length === 3) {
    if (p[0].length === 4) return mk(Number(p[0]), Number(p[1]), Number(p[2]));
    return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  }
  const d4 = new Date(s);
  return isNaN(d4.getTime()) ? null : d4;
}
function parseAmount(v) {
  let s = String(v === null || v === undefined ? '' : v).trim();
  if (!s) return 0;
  s = s.replace(/[^0-9.,\-]/g, '');
  if (s.indexOf(',') >= 0) {
    s = s.replace(/\./g, '').replace(/,/g, '.');
  } else if (s.indexOf('.') >= 0) {
    const p = s.split('.');
    if (p.length > 2 || p[1].length === 3) s = p.join('');
  }
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row);
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function money(n) { return new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(n || 0); }
function parrafo(nivel, dias, importe) {
  if (nivel >= 3) return 'El importe sigue pendiente ' + dias + ' días después del vencimiento. Te pedimos que lo regularices esta semana; si ya lo has pagado, avísanos para cuadrar la contabilidad. Si no podemos confirmar el pago, nos pondremos en contacto para acordar un aplazamiento.';
  if (nivel === 2) return 'Han pasado ' + dias + ' días desde el vencimiento y no consta el pago. Te agradeceríamos que nos indicaras la fecha prevista de pago o que realizaras la transferencia con los datos de abajo.';
  return 'El importe de ' + importe + ' venció hace ' + dias + ' días y todavía no consta en nuestra cuenta. Si ya lo has pagado, ignora este mensaje: los pagos pueden tardar un par de días en reflejarse.';
}

const rows = $input.all().map(function (i) { return i.json; });
const grupos = new Map();

for (const row of rows) {
  if (norm(val(row, ['Estado'])) !== 'pendiente') continue;
  const venc = parseDate(val(row, ['Fecha_Vencimiento', 'Fecha Vencimiento', 'Vencimiento']));
  if (!venc) continue;
  const dias = Math.floor((HOY.getTime() - venc.getTime()) / 86400000);
  let nivel = 0;
  if (dias >= DIAS_NIVEL3) nivel = 3;
  else if (dias >= DIAS_NIVEL2) nivel = 2;
  else if (dias >= DIAS_NIVEL1) nivel = 1;
  if (nivel === 0) continue;
  const nivelActual = Number(val(row, ['Nivel'])) || 0;
  if (nivel <= nivelActual) continue;
  const ultimo = parseDate(val(row, ['Ultimo_Recordatorio', 'Último recordatorio']));
  if (ultimo && iso(ultimo) === HOY_ISO) continue;
  const email = String(val(row, ['Email', 'Correo'])).trim();
  if (!email || email.indexOf('@') < 1) continue;
  const id = String(val(row, ['ID', 'Id'])).trim();
  if (!id) continue;
  const importe = parseAmount(val(row, ['Importe', 'Total']));
  const cliente = String(val(row, ['Cliente', 'Razón social', 'Razon social'])).trim() || email;
  const concepto = String(val(row, ['Concepto', 'Descripción', 'Descripcion'])).trim() || 'Servicios profesionales';
  const recordatorios = Number(val(row, ['Recordatorios'])) || 0;
  const key = email.toLowerCase();
  if (!grupos.has(key)) {
    grupos.set(key, { to: email, email: email, cliente: cliente, facturas: [], importeTotal: 0, nivelMax: 0, diasMax: 0 });
  }
  const g = grupos.get(key);
  g.facturas.push({ ID: id, concepto: concepto, importe: importe, importeFmt: money(importe), vencimiento: fecha(venc), dias: dias, nivel: nivel, recordatorios: recordatorios });
  g.importeTotal += importe;
  if (nivel > g.nivelMax) g.nivelMax = nivel;
  if (dias > g.diasMax) g.diasMax = dias;
}

const salida = [];
for (const g of grupos.values()) {
  const lineas = [];
  lineas.push('Hola ' + g.cliente + ':');
  lineas.push('');
  lineas.push('Te escribimos de ' + EMPRESA + ' en relación con ' + (g.facturas.length === 1 ? 'esta factura' : 'estas facturas') + ':');
  lineas.push('');
  for (const f of g.facturas) {
    lineas.push('· ' + f.ID + ' — ' + f.concepto);
    lineas.push('  Importe: ' + f.importeFmt + ' · vencimiento: ' + f.vencimiento + ' (' + f.dias + ' días)');
  }
  lineas.push('');
  lineas.push('Total pendiente: ' + money(g.importeTotal));
  lineas.push('');
  lineas.push(parrafo(g.nivelMax, g.diasMax, money(g.importeTotal)));
  lineas.push('');
  const ids = g.facturas.map(function (f) { return f.ID; });
  lineas.push('Puedes marcar el pago como realizado en un clic (marca ' + (ids.length === 1 ? 'la factura' : 'las ' + ids.length + ' facturas') + ' del listado):');
  lineas.push(BASE_URL + LINK_PATH + '?ids=' + encodeURIComponent(ids.join(',')) + '&k=' + encodeURIComponent(ids[0]));
  lineas.push('');
  lineas.push('Datos para la transferencia:');
  lineas.push('IBAN: ' + IBAN);
  lineas.push('Beneficiario: ' + EMPRESA);
  lineas.push('Referencia: ' + ids.join(' / '));
  lineas.push('');
  lineas.push('Si ya has realizado el pago, ignora este mensaje: el enlace también sirve para dejarlo registrado.');
  lineas.push('');
  lineas.push('Un saludo,');
  lineas.push(EMPRESA);
  const subject = g.facturas.length === 1
    ? 'Factura ' + g.facturas[0].ID + ' — vencida el ' + g.facturas[0].vencimiento + ' (' + g.facturas[0].dias + ' días)'
    : g.facturas.length + ' facturas pendientes — ' + money(g.importeTotal);
  salida.push({ json: {
    to: g.to,
    cliente: g.cliente,
    subject: subject,
    body: lineas.join(NL),
    nivel: g.nivelMax,
    facturas: g.facturas,
    nFacturas: g.facturas.length,
    importeTotal: g.importeTotal,
    importeFmt: money(g.importeTotal),
    hoy: HOY_ISO,
    hoyFmt: fecha(HOY)
  } });
}
return salida;

// FlowKit · Cobros vencidos — una fila de hoja por factura recordada
const clientes = $input.all().map(function (i) { return i.json; });
const out = [];
for (const c of clientes) {
  for (const f of c.facturas) {
    out.push({ json: {
      ID: f.ID,
      Nivel: String(f.nivel),
      Recordatorios: String((Number(f.recordatorios) || 0) + 1),
      Ultimo_Recordatorio: c.hoy
    } });
  }
}
return out;

// FlowKit · Cobros vencidos — resumen del día para el equipo
const clientes = $('Clasificar cartera').all().map(function (i) { return i.json; });
const NL = String.fromCharCode(10);
let importe = 0;
let facturas = 0;
const porNivel = { 1: 0, 2: 0, 3: 0 };
for (const c of clientes) {
  importe += c.importeTotal;
  facturas += c.nFacturas;
  porNivel[c.nivel] = (porNivel[c.nivel] || 0) + 1;
}
function money(n) { return new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(n || 0); }
const orden = clientes.slice().sort(function (a, b) { return b.importeTotal - a.importeTotal; });
const lineas = [];
lineas.push('Cobros · ' + (clientes[0] ? clientes[0].hoyFmt : ''));
lineas.push(clientes.length + ' clientes · ' + facturas + ' facturas · ' + money(importe) + ' reclamado');
lineas.push('Nivel 1: ' + porNivel[1] + ' · Nivel 2: ' + porNivel[2] + ' · Nivel 3: ' + porNivel[3]);
lineas.push('');
for (const c of orden.slice(0, 10)) {
  lineas.push('· ' + c.cliente + ' — ' + c.importeFmt + ' (' + c.nFacturas + (c.nFacturas === 1 ? ' factura' : ' facturas') + ', nivel ' + c.nivel + ')');
}
if (orden.length > 10) lineas.push('… y ' + (orden.length - 10) + ' clientes más');
return [{ json: { text: lineas.join(NL) } }];

